/**
 * EB Garamond (latin subset, weight 400 upright + italic), base64 woff2.
 *
 * Embedded rather than linked: the renderer runs headless Chrome with no
 * network font access, so a `@font-face` pointing at Google Fonts would
 * silently fall back to a system serif and the cut would ship in the wrong
 * typeface. Kept in its own file because the payload dwarfs the code that
 * registers it.
 *
 * Source: fonts.gstatic.com, EB Garamond v33 (OFL).
 */

export const EB_GARAMOND_LATIN_WOFF2_BASE64 =
  ""

export const EB_GARAMOND_LATIN_ITALIC_WOFF2_BASE64 =
  ""
